package com.alpharip.staffmod.cases.evidencecaselinker; public final class EvidenceLink {private final String evidenceReference,caseId,note;private final long createdAt;public EvidenceLink(String r,String c,String n,long t){if(r==null||r.trim().isEmpty()||c==null||c.trim().isEmpty())throw new IllegalArgumentException("Reference and case ID required");evidenceReference=r.trim();caseId=c.trim();note=n==null?"":n.trim();createdAt=t;}public String getEvidenceReference(){return evidenceReference;}public String getCaseId(){return caseId;}public String getNote(){return note;}public long getCreatedAt(){return createdAt;}}